/**
 * Identifies the deal to pull. Deliberately not keyed on a registration number: under the Motor Vehicles Act an RTO will not register a vehicle without live insurance, so a new vehicle has no registration number at the moment the policy is bought. The keys that do exist at that point are the dealer's own deal identifier and the chassis number of the allocated stock unit. Supply at least one — dealId wins if both are given, because it resolves a whole deal rather than just a vehicle.
 */
export interface DmsPullInput {
  /**
     * The dealer's own deal or booking identifier, e.g. HMC-DL-2026-000183. Preferred: a deal is customer plus vehicle plus finance, where a chassis is only the vehicle.
     * @minLength 1
     */
  dealId?: string;
  /**
     * Chassis number (VIN) of the allocated unit, e.g. MBLKAR0921NK18337. Present on Form 21 before any RC exists, and unlike a registration number it never changes on transfer or re-registration.
     * @minLength 1
     */
  chassisNo?: string;
}

export interface BrowserScrapeInput {
  /**
     * Dealer portal URL to scrape
     * @minLength 1
     */
  url: string;
  /**
     * Optional login username for the portal
     * @nullable
     */
  username?: string | null;
  /**
     * Optional login password for the portal
     * @nullable
     */
  password?: string | null;
}

/**
 * Preferred OCR engine. "auto" (the default) walks the configured priority order. Naming an engine puts it first but still falls through to the rest unless allowFallback is false. The stub engine is never reached automatically — it must be named explicitly.
 */
export type OcrInputModel = typeof OcrInputModel[keyof typeof OcrInputModel];


export const OcrInputModel = {
  auto: 'auto',
  paddleocr: 'paddleocr',
  'qwen-vl': 'qwen-vl',
  olmocr: 'olmocr',
  'gpt-vision': 'gpt-vision',
  gemini: 'gemini',
  openrouter: 'openrouter',
  stub: 'stub',
} as const;

export interface OcrInput {
  /** Base64-encoded image (JPEG/PNG) or PDF content */
  imageBase64: string;
  /** MIME type of the uploaded file, e.g. image/jpeg or application/pdf */
  mimeType: string;
  /** Preferred OCR engine. "auto" (the default) walks the configured priority order. Naming an engine puts it first but still falls through to the rest unless allowFallback is false. The stub engine is never reached automatically — it must be named explicitly. */
  model?: OcrInputModel;
  /** When false, only the named engine is tried and its failure is returned as-is. Defaults to true. Ignored when model is "auto". */
  allowFallback?: boolean;
}

export type OcrEngineStatusEngineId = typeof OcrEngineStatusEngineId[keyof typeof OcrEngineStatusEngineId];


export const OcrEngineStatusEngineId = {
  paddleocr: 'paddleocr',
  'qwen-vl': 'qwen-vl',
  olmocr: 'olmocr',
  'gpt-vision': 'gpt-vision',
  gemini: 'gemini',
  openrouter: 'openrouter',
  stub: 'stub',
} as const;

/**
 * An OCR engine's configuration and live availability
 */
export interface OcrEngineStatus {
  engineId: OcrEngineStatusEngineId;
  label: string;
  /** Lower is tried first */
  priority: number;
  /** Operator toggle, stored in the database */
  isEnabled: boolean;
  /** False for engines that are stubs pending real integration */
  isImplemented: boolean;
  /** True when the engine's API key is present in the environment */
  isConfigured: boolean;
  /** isEnabled AND isImplemented AND isConfigured */
  isAvailable: boolean;
  /** Whether this engine can be selected by the automatic chain */
  autoEligible: boolean;
  /** Human-readable explanation of the current status */
  statusReason: string;
  /** @nullable */
  requiredEnvVar: string | null;
}

